$fotos=is_array($imovel['fotos']??null)?$imovel['fotos']:[];$capa=null;foreach($fotos as $foto)if(($foto['tipo']??'')==='capa'&&!$capa)$capa=$foto;$share=gallery_url($id);$owners=supabase_request('GET','/rest/v1/proprietarios?select=id,nome,tipo&order=nome.asc');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar <?=e($imovel['nome'])?> · Central Imóveis</title><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"></head><body><main class="container pequeno"><a class="voltar" href="index.php">← Voltar aos imóveis</a><?php render_nav('imoveis'); ?><header class="page-head"><div><span class="eyebrow">IMÓVEL · <?=e($imovel['codigo'])?></span><h1>Editar imóvel</h1><p class="subtitulo"><?=e($imovel['nome'])?></p></div></header><?php if($m=flash('error')):?><div class="alerta erro"><?=e($m)?></div><?php endif;?><?php if($m=flash('success')):?><div class="alerta sucesso"><?=e($m)?></div><?php endif;?>
<form action="atualizar.php" method="POST" class="formulario"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>">
<section class="form-card"><div class="form-card-title"><span>01</span><div><strong>Identificação</strong><small>Nome, referência e vínculo.</small></div></div><div class="grid"><label>Código *<input name="codigo" required maxlength="50" value="<?=e($imovel['codigo'])?>"></label><label>Nome *<input name="nome" required maxlength="150" value="<?=e($imovel['nome'])?>"></label></div><label>Proprietário<select name="proprietario_id"><option value="">Sem proprietário vinculado</option><?php foreach((array)$owners as $owner):?><option value="<?= (int)$owner['id'] ?>" <?=((int)($imovel['proprietario_id']??0)===(int)$owner['id'])?'selected':''?>><?=e($owner['nome'])?><?=($owner['tipo']??'pf')==='pj'?' · PJ':''?></option><?php endforeach;?></select></label><input type="hidden" name="proprietario" value="<?=e($imovel['proprietario']??'')?>"></section>
<section class="form-card"><div class="form-card-title"><span>02</span><div><strong>Endereço inteligente</strong><small>CEP, mapa e localização interna.</small></div></div><div class="cep-row"><label>CEP<input id="cep" name="cep" inputmode="numeric" maxlength="9" value="<?=e($imovel['cep']??'')?>"><small id="cepStatus" class="field-status">Atualize o endereço pelo CEP.</small></label><button id="cepBtn" class="botao secundario" type="button">Buscar CEP</button></div><div class="grid"><label>Rua / logradouro<input id="endereco" name="endereco" maxlength="250" value="<?=e($imovel['endereco']??'')?>"></label><label>Número<input id="numero" name="numero" maxlength="20" value="<?=e($imovel['numero']??'')?>"></label></div><div class="grid"><label>Complemento<input id="complemento" name="complemento" maxlength="120" value="<?=e($imovel['complemento']??'')?>"></label><label>Bairro<input id="bairro" name="bairro" maxlength="100" value="<?=e($imovel['bairro']??'')?>"></label></div><div class="grid"><label>Cidade<input id="cidade" name="cidade" maxlength="100" value="<?=e($imovel['cidade']??'São Sebastião')?>"></label><label>UF<input id="uf" name="uf" maxlength="2" value="<?=e($imovel['uf']??'SP')?>"></label></div><div id="pickerMap" class="map-picker"></div><div class="grid"><label>Latitude<input id="latitude" type="number" step="any" name="latitude" value="<?=e($imovel['latitude']??'')?>"></label><label>Longitude<input id="longitude" type="number" step="any" name="longitude" value="<?=e($imovel['longitude']??'')?>"></label></div><p class="map-help">A posição exata fica somente na Central. O anúncio público usa uma área aproximada.</p></section>
<section class="form-card"><div class="form-card-title"><span>03</span><div><strong>Características</strong><small>O que o cliente encontra no imóvel.</small></div></div><div class="grid quatro"><label>Capacidade<input type="number" name="capacidade" min="0" value="<?= (int)$imovel['capacidade']?>"></label><label>Dormitórios<input type="number" name="dormitorios" min="0" value="<?= (int)$imovel['dormitorios']?>"></label><label>Suítes<input type="number" name="suites" min="0" value="<?= (int)$imovel['suites']?>"></label><label>Distância da praia (m)<input type="number" name="distancia_praia" min="0" value="<?= (int)$imovel['distancia_praia']?>"></label></div><div class="checks"><label><input type="checkbox" name="suite_terrea" <?=!empty($imovel['suite_terrea'])?'checked':''?>> Suíte térrea</label><label><input type="checkbox" name="piscina" <?=!empty($imovel['piscina'])?'checked':''?>> Piscina</label><label><input type="checkbox" name="churrasqueira" <?=!empty($imovel['churrasqueira'])?'checked':''?>> Churrasqueira</label><label><input type="checkbox" name="ar_condicionado" <?=!empty($imovel['ar_condicionado'])?'checked':''?>> Ar-condicionado</label></div><label class="other-field">Outros <span class="field-hint">+</span><input name="observacao" maxlength="500" value="<?=e($imovel['observacao']??'')?>" placeholder="Ex.: varanda, sauna, elevador, vista aberta..."></label></section>
<section class="form-card"><div class="form-card-title"><span>04</span><div><strong>Comercial</strong><small>Informações usadas na apresentação.</small></div></div><label>Diária base<input type="number" name="diaria" min="0" step="0.01" value="<?=e($imovel['diaria'])?>"></label><label>Descrição<textarea name="descricao" rows="7" placeholder="Descreva os principais diferenciais e condições do imóvel"><?=e($imovel['descricao']??'')?></textarea></label><label class="check-unico"><input type="checkbox" name="ativo" <?=!empty($imovel['ativo'])?'checked':''?>> Imóvel ativo</label></section>
<section class="form-card"><div class="form-card-title"><span>05</span><div><strong>Fotos e compartilhamento</strong><small>A mesma página funciona como anúncio público.</small></div></div><div class="share-actions"><div><strong>Enviar o anúncio</strong><p>O link leva à página de fotos, descrição, dados do corretor e download da galeria em PDF.</p></div><div class="acoes-form"><a class="botao secundario" target="_blank" href="<?=e($share)?>">Abrir anúncio</a><button class="botao secundario" type="button" onclick="downloadPdf()">Baixar PDF</button><a class="botao secundario" href="download_fotos.php?id=<?=$id?>">Baixar ZIP</a></div></div><div class="upload-row"><label class="upload-box"><span class="upload-icone">＋</span><span><strong>Escolher capa</strong><small>Uma imagem para reconhecer o imóvel.</small></span><input id="capaInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label><?php if($capa):?><div class="mini-preview"><img src="<?=e($capa['url'])?>" alt="Capa"><small>Capa atual</small></div><?php endif;?></div><label class="upload-box"><span class="upload-icone">＋</span><span><strong>Adicionar fotos à biblioteca</strong><small>Selecione quantas quiser. Envio em fila para o Cloudinary.</small></span><input id="bibliotecaInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple></label><div id="uploadStatus" class="upload-status">Nenhum upload em andamento.</div><div id="fila" class="fila"></div></section>
<div class="acoes-form save-zone"><a class="botao secundario" href="contratos.php?imovel=<?=$id?>">Contrato deste imóvel</a><a class="botao secundario" href="index.php">Cancelar</a><button class="botao" type="submit">Salvar alterações</button></div></form><?php render_footer();?></main>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const id=<?=$id?>,csrf=<?=json_encode(csrf_token())?>;let lat=Number(<?=json_encode($imovel['latitude'])?>),lng=Number(<?=json_encode($imovel['longitude'])?>);const latInput=document.getElementById('latitude'),lngInput=document.getElementById('longitude');const map=L.map('pickerMap');L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);let marker=null;function setPoint(a,b){latInput.value=a.toFixed(7);lngInput.value=b.toFixed(7);if(marker)marker.setLatLng([a,b]);else marker=L.marker([a,b],{draggable:true}).addTo(map).on('dragend',e=>{const p=e.target.getLatLng();setPoint(p.lat,p.lng)});map.setView([a,b],16)}if(Number.isFinite(lat)&&Number.isFinite(lng))setPoint(lat,lng);else map.setView([-23.76,-45.72],12);map.on('click',e=>setPoint(e.latlng.lat,e.latlng.lng));const cep=document.getElementById('cep'),cepStatus=document.getElementById('cepStatus');async function buscarCep(){const v=cep.value.replace(/\D/g,'');if(v.length!==8){cepStatus.textContent='Digite um CEP com 8 números.';return}cepStatus.textContent='Consultando…';const r=await fetch('https://viacep.com.br/ws/'+v+'/json/');const d=await r.json();if(d.erro){cepStatus.textContent='CEP não encontrado.';return}document.getElementById('endereco').value=d.logradouro||'';document.getElementById('bairro').value=d.bairro||'';document.getElementById('cidade').value=d.localidade||'';document.getElementById('uf').value=d.uf||'';cepStatus.textContent='Endereço atualizado.'}document.getElementById('cepBtn').addEventListener('click',buscarCep);cep.addEventListener('blur',()=>{if(cep.value.replace(/\D/g,'').length===8)buscarCep()});async function enviar(file,tipo){const fd=new FormData();fd.append('id',id);fd.append('csrf',csrf);fd.append('tipo',tipo);fd.append('foto',file);const r=await fetch('upload_foto.php',{method:'POST',body:fd,credentials:'same-origin'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Falha no upload');return j}const capaInput=document.getElementById('capaInput'),bibliotecaInput=document.getElementById('bibliotecaInput'),statusEl=document.getElementById('uploadStatus'),fila=document.getElementById('fila');capaInput.addEventListener('change',async()=>{if(!capaInput.files[0])return;statusEl.textContent='Enviando capa…';try{await enviar(capaInput.files[0],'capa');location.reload()}catch(e){statusEl.textContent=e.message}});bibliotecaInput.addEventListener('change',async()=>{const files=[...bibliotecaInput.files];if(!files.length)return;fila.innerHTML='';for(let i=0;i<files.length;i++){const el=document.createElement('div');el.className='fila-item';el.textContent=(i+1)+' de '+files.length+' · '+files[i].name+' · enviando';fila.appendChild(el);try{await enviar(files[i],'biblioteca');el.textContent=(i+1)+' de '+files.length+' · '+files[i].name+' · enviada';el.classList.add('ok')}catch(e){el.textContent=(i+1)+' de '+files.length+' · '+files[i].name+' · '+e.message;el.classList.add('erro')}}statusEl.textContent='Fila concluída.';bibliotecaInput.value='';setTimeout(()=>location.reload(),700)});async function downloadPdf(){window.open(<?=json_encode($share.'&pdf=1')?>,'_blank')}
</script><style>.map-picker{height:360px;border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-top:12px}.map-help{color:var(--muted);font-size:12px}.other-field{position:relative}.field-hint{display:inline-grid;place-items:center;width:18px;height:18px;border-radius:50%;background:var(--accent);color:#fff;font-size:12px;font-weight:900}.share-actions{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:18px;border:1px solid var(--line);border-radius:16px;background:var(--surface-2)}.share-actions p{margin:5px 0 0;color:var(--muted);font-size:12px}.foto-thumb img{display:block;width:100%;height:120px;object-fit:cover}@media(max-width:650px){.share-actions{display:block}.share-actions .acoes-form{margin-top:14px}.share-actions .botao{width:100%}}</style></body></html>